"""Language for the human-readable text generated by semantic compilation."""

from typing import Literal

SemanticOutputLanguage = Literal["en", "zh-CN"]
DEFAULT_SEMANTIC_OUTPUT_LANGUAGE: SemanticOutputLanguage = "en"


def semantic_text_prompt(prompt: str, language: SemanticOutputLanguage) -> str:
    language_name = (
        "Simplified Chinese (简体中文)" if language == "zh-CN" else "English"
    )
    return (
        f"{prompt}\n\n"
        f"Write generated business names, display labels, and descriptions in {language_name}. "
        "Apply that language's natural naming conventions regardless of the language "
        "of the evidence. Preserve standard abbreviations where appropriate. "
        "Copy physical identifiers, provided SQL expressions, literal data values, and "
        "explicitly quoted aliases verbatim when you include them."
    )
